import { gsap } from 'gsap';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, Object3D } = ctx.THREE;

  // Root group for the badge
  const root = new Group();
  root.position.set(2.5, -0.2, 0);
  root.scale.set(1, 1, 1);

  // Cleanup registry
  const timelines = [];
  const cleanups = [];

  // State for interactions
  let isHovered = false;
  let enterTimeline = null;

  // Load the GLB mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene;
    scene.traverse((node) => {
      if (node.isMesh) {
        // Keep existing PBR materials from the GLB
        // Enhance with accent rim light via material
        if (node.material) {
          const originalMaterial = node.material;

          // If it's a standard material, we can layer an enhanced version
          if (originalMaterial.isMeshStandardMaterial || originalMaterial.isMeshPhysicalMaterial) {
            // Keep the original for geometry/base properties
            // The GLB already has proper PBR setup (metalness, roughness, etc.)

            // Add a rim light effect by boosting emissive slightly on the accent color
            const accentColor = uniform(new ctx.THREE.Color('#ff2a38'));
            const rimStrength = uniform(0.3);

            // Capture the original emissive and layer the rim
            const baseEmissive = originalMaterial.emissive || new ctx.THREE.Color(0, 0, 0);
            originalMaterial.emissive.copy(baseEmissive);
          }
        }

        // Cast shadow for contact with stage
        node.castShadow = true;
        node.receiveShadow = true;
      }
    });

    root.add(scene);

    // Apply cinematic primitives
    // 1. Parallax scroll on scroll trigger
    if (config.cinematicPrimitives) {
      for (const prim of config.cinematicPrimitives) {
        if (prim.name === 'parallax-scroll' && prim.trigger === 'scroll') {
          const parallaxResult = ctx.primitives['parallax-scroll'](root, prim.params);
          cleanups.push(parallaxResult.cleanup);
        }
        if (prim.name === 'magnetic-cursor' && prim.trigger === 'hover') {
          const magneticResult = ctx.primitives['magnetic-cursor'](root, prim.params);
          cleanups.push(magneticResult.cleanup);
        }
      }
    }
  });

  // Hover interaction: rise-in animation (subtle 0.15 scene units)
  root.userData.handlers = {
    onHover: () => {
      if (isHovered) return;
      isHovered = true;

      if (enterTimeline) enterTimeline.kill();
      enterTimeline = gsap.timeline();

      // Subtle rise (0.15 units up from current position)
      enterTimeline.to(root.position, {
        y: root.position.y + 0.15,
        duration: 0.5,
        ease: 'power2.out'
      }, 0);

      timelines.push(enterTimeline);
    },
    onHoverOut: () => {
      if (!isHovered) return;
      isHovered = false;

      if (enterTimeline) enterTimeline.kill();
      enterTimeline = gsap.timeline();

      // Settle back down with weighted-settle easing
      enterTimeline.to(root.position, {
        y: -0.2,
        duration: 0.9,
        ease: 'power4.out'
      }, 0);

      timelines.push(enterTimeline);
    },
    onClick: () => {
      ctx.emit('hub-journal.select', {});
    }
  };

  // Cleanup function
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    cleanups.forEach((fn) => fn());
    timelines.length = 0;
    cleanups.length = 0;

    root.traverse((node) => {
      if (node.isMesh) {
        node.geometry?.dispose();
        if (node.material) {
          if (Array.isArray(node.material)) {
            node.material.forEach((m) => m.dispose());
          } else {
            node.material.dispose();
          }
        }
      }
    });
  };

  return root;
}
